// Build the candidate page list per company. Nothing is fetched here.
// Only a handful of conventional paths: this is a research pass, not a crawl.

const PATHS = ['', '/about', '/careers', '/jobs', '/blog', '/engineering'];
const USER_AGENT = 'AiSalesMachineBot/1.0 (+https://github.com/urosorolicki/ai-sales)';

return $input.all().map((item) => {
  const c = item.json;
  const site = typeof c.website === 'string' && /^https?:\/\//i.test(c.website)
    ? c.website.replace(/\/+$/, '')
    : 'https://' + c.domain;

  return {
    json: {
      ...c,
      base_url: site,
      robots_url: site + '/robots.txt',
      candidate_urls: PATHS.map((p) => site + p),
      user_agent: USER_AGENT,
    },
  };
});

// Apply robots.txt. docs/security.md and the WF-02 row in docs/workflows.md both
// require it, and a research bot that ignores robots.txt is the kind of thing
// that gets an IP blocked and a reputation with it.
//
// Longest-match wins between Allow and Disallow, which is what Google and the
// RFC 9309 draft both specify. A missing or unreadable robots.txt means allow:
// that is the documented default, not an assumption.

function parseRobots(text, agent) {
  const groups = [];
  let current = null;
  for (const rawLine of String(text).split(/\r?\n/)) {
    const line = rawLine.replace(/#.*$/, '').trim();
    if (!line) continue;
    const idx = line.indexOf(':');
    if (idx === -1) continue;
    const field = line.slice(0, idx).trim().toLowerCase();
    const value = line.slice(idx + 1).trim();

    if (field === 'user-agent') {
      if (!current || current.rules.length) {
        current = { agents: [], rules: [] };
        groups.push(current);
      }
      current.agents.push(value.toLowerCase());
    } else if ((field === 'allow' || field === 'disallow') && current) {
      current.rules.push({ allow: field === 'allow', path: value });
    }
  }

  const token = agent.split('/')[0].toLowerCase();
  const exact = groups.find((g) => g.agents.includes(token));
  const wildcard = groups.find((g) => g.agents.includes('*'));
  return (exact || wildcard || { rules: [] }).rules;
}

function isAllowed(path, rules) {
  let best = null;
  for (const rule of rules) {
    // An empty Disallow means "allow everything" and matches nothing.
    if (rule.path === '') continue;
    const pattern = rule.path.replace(/\*+$/, '');
    if (!path.startsWith(pattern)) continue;
    if (best === null || pattern.length > best.length) {
      best = { length: pattern.length, allow: rule.allow };
    }
  }
  return best === null ? true : best.allow;
}

const companies = $('Candidate URLs').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const company = companies[i].json;
  const res = $input.all()[i].json ?? {};

  // neverError is on, so a 404 arrives as data, not as an exception. Either way
  // an unreadable robots.txt means no restrictions were published.
  const body = typeof res.data === 'string' ? res.data : '';
  const rules = body ? parseRobots(body, company.user_agent) : [];

  const allowed = [];
  const blocked = [];
  for (const url of company.candidate_urls) {
    const path = url.slice(company.base_url.length) || '/';
    (isAllowed(path, rules) ? allowed : blocked).push(url);
  }

  out.push({
    json: {
      ...company,
      urls: allowed,
      robots_blocked: blocked,
      robots_rules_found: rules.length,
    },
  });
}

return out;

// One item per fetched page arrives here. Group them back into one item per
// company and turn the HTML into something worth sending to a model.
//
// Everything is capped. An unbounded page is an unbounded bill, and a careers
// page with a thousand listings is not more informative than the first slice.

const MAX_CHARS_PER_PAGE = 6000;
const MAX_CHARS_TOTAL = 24000;

function htmlToText(html) {
  return String(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<\/(p|div|li|h[1-6]|tr|section|article)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;/gi, "'")
    .replace(/[ \t ]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

// The HTTP Request node replaces the item json with the response, so the
// company each page belongs to is read back from Split URLs by index. n8n keeps
// one output item per input item here, so the indexes line up.
const pages = $input.all();
const context = $('Split URLs').all();
const byCompany = new Map();

for (let i = 0; i < pages.length; i++) {
  const j = { ...context[i].json, ...(pages[i].json ?? {}) };
  const key = j.company_id;
  if (!key) continue;

  if (!byCompany.has(key)) {
    byCompany.set(key, {
      company_id: j.company_id,
      name: j.name,
      domain: j.domain,
      website: j.website,
      industry: j.industry,
      base_url: j.base_url,
      prior_failures: j.prior_failures ?? 0,
      robots_blocked: j.robots_blocked ?? [],
      sources: [],
      fetch_failures: [],
      sections: [],
    });
  }
  const bucket = byCompany.get(key);

  // An HTTP error or a network failure is evidence of absence, not a crash.
  const res = pages[i].json ?? {};
  const failed = res.error !== undefined || typeof res.data !== 'string' || res.data === '';
  if (failed) {
    const reason = res.error
      ? (typeof res.error === 'string' ? res.error : (res.error.message ?? 'request failed'))
      : 'empty response';
    bucket.fetch_failures.push(j.url + ' (' + reason + ')');
    continue;
  }

  const text = htmlToText(res.data);
  if (text.length < 40) {
    bucket.fetch_failures.push(j.url + ' (no usable text)');
    continue;
  }

  bucket.sources.push(j.url);
  bucket.sections.push('### SOURCE: ' + j.url + '\n' + text.slice(0, MAX_CHARS_PER_PAGE));
}

const out = [];
for (const bucket of byCompany.values()) {
  let material = bucket.sections.join('\n\n');
  let truncated = false;
  if (material.length > MAX_CHARS_TOTAL) {
    material = material.slice(0, MAX_CHARS_TOTAL);
    truncated = true;
  }
  const { sections, ...rest } = bucket;
  out.push({
    json: {
      ...rest,
      material,
      material_chars: material.length,
      material_truncated: truncated,
      pages_fetched: bucket.sources.length,
      // Playwright is not deployed. A page that needs JavaScript to render is
      // recorded as unknown rather than silently treated as empty.
      rendering_unavailable: bucket.sources.length === 0 && bucket.fetch_failures.length > 0,
    },
  });
}

return out;

// Build the Ollama triage request. Deliberately cheap: a short prompt, a small
// slice of the material and a tiny output budget. Triage runs for every company,
// including the ones that go on to the expensive model, so its cost is paid
// every time and must stay low.

const MAX_TRIAGE_CHARS = 4000;
const MODEL = $env.OLLAMA_MODEL || 'llama3.1:8b';

// The source headers carry the candidate paths - /careers, /blog, /engineering -
// which are exactly the keywords triage looks for. Left in, the filter answers
// "yes, there is an engineering section" for any site at all, because the URL
// said so. Triage judges the text; only the research call needs the URLs.
function neutraliseSources(text) {
  return String(text).replace(/^### SOURCE: \S+[ \t]*$/gm, '### PAGE');
}

const SYSTEM = "You are a triage filter for a DevOps and SRE consultancy's lead pipeline.\n\nYou are given text fetched from one company's own website. Decide exactly one\nthing: is there anything here worth paying a stronger model to analyse?\n\nAnswer true if the material mentions ANY of:\n- engineering or technical hiring of any kind\n- cloud, infrastructure, Kubernetes, Docker, containers, CI/CD, deployment,\n  platform, SRE, DevOps, Terraform\n- an engineering blog, a status page, public repositories\n- scaling, reliability, outages, incidents, migrations, performance\n\nAnswer false ONLY if the material is plainly a marketing or brochure site with no\nengineering content whatsoever, or there is essentially no text to judge.\n\nWHEN IN DOUBT, ANSWER TRUE. Answering false permanently discards a company that\nis never looked at again. Answering true costs a fraction of a cent. Caution in\nthis direction is correct, not lazy.\n\nDo not analyse the company. Do not list its technology stack. Do not judge\nwhether it is a good customer. Only decide whether there is evidence here.\n\nReturn strict JSON only.";

// Ollama 0.5+ takes a JSON Schema in `format` and constrains generation to it.
// That fixes the shape; it does not make the judgement good, which is why this
// model is only asked a yes/no question.
const SCHEMA = {
  "type": "object",
  "properties": {
    "worth_researching": {
      "type": "boolean"
    },
    "evidence_seen": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "reason": {
      "type": "string"
    }
  },
  "required": [
    "worth_researching",
    "evidence_seen",
    "reason"
  ]
};

const material = $('Group Material').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const run = $input.all()[i].json;
  const m = material[i].json;

  out.push({
    json: {
      triage_run_id: run.id,
      company_id: m.company_id,
      name: m.name,
      domain: m.domain,
      pages_fetched: m.pages_fetched,
      material_chars: m.material_chars,
      triage_request: {
        model: MODEL,
        stream: false,
        format: SCHEMA,
        options: { temperature: 0, num_predict: 256, num_ctx: 8192 },
        messages: [
          { role: 'system', content: SYSTEM },
          {
            role: 'user',
            content:
              'Company: ' + m.name + '\n' +
              'Domain: ' + m.domain + '\n\n' +
              (m.material
                ? neutraliseSources(m.material).slice(0, MAX_TRIAGE_CHARS)
                : '(nothing could be fetched)'),
          },
        ],
      },
    },
  });
}

return out;

// Read the triage verdict. This node fails open on purpose.
//
// If Ollama is down, slow, or returns something unusable, the company goes to
// the expensive model anyway. The filter exists to save money, and a broken
// filter must cost money rather than silently discard leads.

const requests = $('Build Triage Request').all();
const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const req = requests[i].json;
  const res = $input.all()[i].json ?? {};

  let worth = true;
  let reason = '';
  let evidence = [];
  let failedOpen = false;

  // Nothing was fetched, so there is nothing for any model to research. This is
  // mechanical, not a judgement, and it is checked before the model's opinion.
  if (req.pages_fetched === 0) {
    worth = false;
    reason = 'No page could be fetched from this domain';
  } else if (res.error !== undefined) {
    failedOpen = true;
    reason = 'Triage unavailable (' +
      (typeof res.error === 'string' ? res.error : (res.error && res.error.message) || 'unknown') +
      '); passing through to the research model';
  } else {
    const raw = res.message && typeof res.message.content === 'string' ? res.message.content : '';
    let parsed = null;
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      failedOpen = true;
      reason = 'Triage returned unparseable JSON; passing through to the research model';
    }
    if (parsed && typeof parsed.worth_researching === 'boolean') {
      worth = parsed.worth_researching;
      reason = typeof parsed.reason === 'string' ? parsed.reason : '';
      evidence = Array.isArray(parsed.evidence_seen) ? parsed.evidence_seen.filter((e) => typeof e === 'string') : [];
    } else if (parsed) {
      failedOpen = true;
      reason = 'Triage gave no boolean verdict; passing through to the research model';
    }
  }

  out.push({
    json: {
      ...req,
      worth_researching: worth,
      triage_reason: reason,
      triage_evidence: evidence,
      triage_failed_open: failedOpen,
      triage_model: req.triage_request.model,
    },
  });
}

return out;

// Assemble the research request. Runs once per item: this node sits after the
// triage branch, where item indexes no longer line up with the nodes before it,
// so the company is reached through n8n's paired-item link rather than by index.
//
// Both the prompt and the schema are read from disk at runtime - ./prompts and
// ./agents are mounted read-only - so prompts/research.md and
// agents/research/schema.json stay the single sources of truth and cannot drift
// from this node.

const MODEL = $env.OLLAMA_RESEARCH_MODEL || 'qwen9-64k:latest';
const MAX_TOKENS = 8000;

// prompts/research.md keeps the system prompt in the first fenced block under
// "## System prompt". Extract exactly that; a heading change must fail loudly
// rather than quietly send the whole markdown file as a prompt.
function extractSystemPrompt(markdown) {
  const section = markdown.split(/^##\s+System prompt\s*$/m)[1];
  if (!section) throw new Error('prompts/research.md: no "## System prompt" heading found');
  const fence = section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/research.md: no fenced block under "## System prompt"');
  const text = fence[1].trim();
  if (text.length < 200) throw new Error('prompts/research.md: system prompt looks truncated');
  return text;
}

const systemPrompt = extractSystemPrompt($('Prompt To Text').first().json.data);

// The draft-07 meta keys are not part of the output contract and the endpoint
// rejects some of them.
const schema = JSON.parse($('Schema To Text').first().json.data);
delete schema.$schema;
delete schema.$id;
delete schema.title;

const run = $input.item.json;
const m = $('Group Material').item.json;

const userContent = [
  'Company: ' + m.name,
  'Domain: ' + m.domain,
  'Industry: ' + (m.industry || 'unknown'),
  '',
  m.sources.length
    ? 'The following material was fetched from the company\'s own site. Cite these URLs.'
    : 'No material could be fetched from this company\'s site.',
  '',
  m.material || '(nothing fetched)',
  '',
  '---',
  'Pages that could not be fetched: ' + (m.fetch_failures.length ? m.fetch_failures.join(', ') : 'none'),
  'Pages disallowed by robots.txt: ' + (m.robots_blocked.length ? m.robots_blocked.join(', ') : 'none'),
  m.material_truncated ? 'The material above was truncated at a character limit.' : '',
  '',
  'Return the JSON object described in the system prompt, and nothing else.',
].join('\n');

return {
  json: {
    agent_run_id: run.id,
    company_id: m.company_id,
    name: m.name,
    domain: m.domain,
    prior_failures: m.prior_failures,
    sources: m.sources,
    model: MODEL,
    // Ollama's OpenAI-compatible endpoint, not /api/chat. On this version
    // /api/chat silently ignores `format` - a two-key schema is not enforced -
    // while response_format with strict json_schema here is. See docs/ollama.md.
    llm_request: {
      model: MODEL,
      temperature: 0.2,
      max_tokens: MAX_TOKENS,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userContent },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'research', strict: true, schema },
      },
    },
  },
};

// Validate the research response against agents/research/schema.json, read from
// disk rather than restated here, so there is one definition of the contract.
// Never throws, never repairs. A response that does not match is an error.
//
// Runs once per item: downstream of the triage branch, so the request this
// response belongs to is reached through the paired-item link, not by index.

const schema = JSON.parse($('Schema To Text').first().json.data);
const props = schema.properties;
const required = schema.required;

const req = $('Build Research Request').item.json;
const res = $input.item.json ?? {};

const errors = [];
const warnings = [];
let parsed = null;
let raw = '';
let usage = null;

if (res.error !== undefined) {
  const e = res.error;
  errors.push('Research model request failed: ' +
    (typeof e === 'string' ? e : (e && e.message) || JSON.stringify(e)));
} else {
  usage = res.usage ?? null;
  const choice = Array.isArray(res.choices) ? res.choices[0] : null;

  if (!choice) {
    errors.push('Response contained no choices');
  } else if (choice.finish_reason === 'length') {
    // The schema alone is long; with a small context window the object is cut
    // off mid-key and the JSON never closes.
    errors.push('Response hit the token limit and is truncated. Use a model with a ' +
      'larger context window (OLLAMA_RESEARCH_MODEL)');
  } else {
    raw = (choice.message && choice.message.content) || '';
    if (!raw.trim()) {
      errors.push('Model returned no text content');
    } else {
      try {
        parsed = JSON.parse(raw);
      } catch (e) {
        errors.push('Response is not valid JSON: ' + e.message);
      }
    }
  }
}

if (parsed !== null && (typeof parsed !== 'object' || Array.isArray(parsed))) {
  errors.push('Response is valid JSON but not a JSON object');
  parsed = null;
}

if (parsed !== null) {
  for (const key of required) {
    if (!(key in parsed)) { errors.push('Missing required key: ' + key); continue; }
    const want = props[key] && props[key].type;
    const value = parsed[key];
    const isArr = Array.isArray(value);
    const ok = want === 'array' ? isArr : (typeof value === want && !isArr);
    if (!ok) {
      errors.push('Key ' + key + ' must be ' + want + ', got ' + (isArr ? 'array' : typeof value));
    }
  }

  const conf = props.confidence;
  if (typeof parsed.confidence === 'number') {
    if (!Number.isFinite(parsed.confidence) ||
        parsed.confidence < conf.minimum || parsed.confidence > conf.maximum) {
      errors.push('confidence must be between ' + conf.minimum + ' and ' + conf.maximum +
        ', got ' + parsed.confidence);
    }
  }

  const services = props.recommended_service.enum;
  if (typeof parsed.recommended_service === 'string' && !services.includes(parsed.recommended_service)) {
    errors.push('recommended_service "' + parsed.recommended_service + '" is not in the allowed set');
  }

  // The signals table has the same CHECK constraint, so a bad value here would
  // be a failed insert later. Reject it now.
  const signalTypes = props.pain_signals.items.properties.signal_type.enum;
  if (Array.isArray(parsed.pain_signals)) {
    for (const s of parsed.pain_signals) {
      if (!s || typeof s !== 'object') { errors.push('pain_signals entries must be objects'); break; }
      if (!signalTypes.includes(s.signal_type)) {
        errors.push('pain_signals.signal_type "' + s.signal_type + '" is not an allowed signal_type');
      }
    }
  }
}

const valid = errors.length === 0;

// Only signals with real text survive: signals.signal has a non-empty CHECK.
const signals = valid
  ? parsed.pain_signals
      .filter((s) => typeof s.signal === 'string' && s.signal.trim() !== '')
      .map((s) => ({
        signal_type: s.signal_type,
        signal: s.signal.trim(),
        source: typeof s.source === 'string' ? s.source : '',
        confidence: typeof s.confidence === 'number' ? s.confidence : 0.5,
      }))
  : [];

if (valid && parsed.pain_signals.length !== signals.length) {
  warnings.push('Dropped ' + (parsed.pain_signals.length - signals.length) + ' pain_signals with empty text');
}
if (valid && new Set(signals.map((s) => s.signal_type)).size === 1 && signals.length > 2) {
  // Local models tend to label every signal the same way. Worth seeing in the
  // audit trail; not worth failing a run over.
  warnings.push('All ' + signals.length + ' pain signals share one signal_type');
}

return {
  json: {
    agent_run_id: req.agent_run_id,
    company_id: req.company_id,
    name: req.name,
    domain: req.domain,
    prior_failures: req.prior_failures,
    valid,
    errors,
    warnings,
    error_message: valid ? null : 'Research validation failed: ' + errors.join('; '),
    analysis: valid ? parsed : null,
    signals,
    raw_response: raw,
    usage,
  },
};
